begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();create temporary table mention_fixture(room uuid,post uuid,mention uuid);grant select,insert,update on mention_fixture to cuevo_api;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);insert into mention_fixture(room)values((internal.community_command('room.create',null,'{"classId":"30000000-0000-4000-8000-000000000001","name":"Mention source group","type":"GROUP","memberIds":["20000000-0000-4000-8000-000000000012","20000000-0000-4000-8000-000000000018"]}','mention-group',repeat('a',64),'mention-test')->>'id')::uuid);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.community_command('post.create',(select room from mention_fixture),'{"body":"Duplicate recipients","replyToId":null,"mentionActorIds":["20000000-0000-4000-8000-000000000018","20000000-0000-4000-8000-000000000018"]}','mention-duplicate',repeat('b',64),'mention-test')$$,'22023',null,'duplicate explicit mention recipients rejected');
select throws_ok($$select internal.community_command('post.create',(select room from mention_fixture),'{"body":"Parent mention denied","replyToId":null,"mentionActorIds":["20000000-0000-4000-8000-000000000072"]}','mention-parent',repeat('c',64),'mention-test')$$,'42501',null,'parent cannot receive pupil room mention');
update mention_fixture set post=(internal.community_command('post.create',room,'{"body":"Check one school explanation","replyToId":null,"mentionActorIds":["20000000-0000-4000-8000-000000000018"]}','mention-post',repeat('d',64),'mention-test')->>'id')::uuid;
select lives_ok($$select internal.community_command('post.create',(select room from mention_fixture),'{"body":"Check one school explanation","replyToId":null,"mentionActorIds":["20000000-0000-4000-8000-000000000018"]}','mention-post',repeat('d',64),'mention-test')$$,'original post key preserves exact singular mention manifest');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000018',true);update mention_fixture set mention=(select(item->>'id')::uuid from jsonb_array_elements(internal.community_list('notifications',null,'{"limit":100}')->'items')item where item->>'kind'='MENTION'and item->>'postId'=(select post::text from mention_fixture));
select is(internal.read_community_mention_source((select mention from mention_fixture))->>'body','Check one school explanation','exact current recipient opens immutable post source');
select lives_ok($$select internal.community_mention_read((select mention from mention_fixture),'mention-read',repeat('e',64),'mention-test')$$,'recipient read confirms exact source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select internal.community_maintenance_command('group',(select room from mention_fixture),'{"name":"Mention source group","state":"CLOSED","expectedRevision":1,"reason":"Teacher closes mention delivery","confirmChange":true}','mention-close',repeat('a',64),'mention-test')is not null as closed;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000018',true);
select throws_ok($$select internal.read_community_mention_source((select mention from mention_fixture))$$,'42501',null,'closed source removes future mention body access');select throws_ok($$select internal.community_mention_read((select mention from mention_fixture),'mention-read',repeat('e',64),'mention-test')$$,'42501',null,'same-key read cannot bypass closed source');select ok(not exists(select 1 from jsonb_array_elements(internal.community_list('notifications',null,'{"limit":100}')->'items')m where m->>'id'=(select mention::text from mention_fixture)),'closed source removes current mention notification');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select internal.community_maintenance_command('group',(select room from mention_fixture),'{"name":"Mention source group","state":"ACTIVE","expectedRevision":2,"reason":"Teacher reopens current group","confirmChange":true}','mention-reopen',repeat('b',64),'mention-test')is not null as reopened;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);select throws_ok($$select internal.read_community_mention_source((select mention from mention_fixture))$$,'42501',null,'parent cannot read exact pupil mention source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select internal.community_command('post.moderate',(select post from mention_fixture),'{"action":"HIDE","reason":"Teacher hides source for review","confirmModeration":true}','mention-hide',repeat('f',64),'mention-test')is not null as hidden;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000018',true);select throws_ok($$select internal.read_community_mention_source((select mention from mention_fixture))$$,'42501',null,'hidden source removes future mention body delivery');select throws_ok($$select internal.community_mention_read((select mention from mention_fixture),'mention-read',repeat('e',64),'mention-test')$$,'42501',null,'same-key read cannot bypass hidden source');
select ok(not has_table_privilege('cuevo_api','app.community_post_mentions','select'),'raw mention identity link grants stay denied');select ok(not has_table_privilege('authenticated','app.community_mention_reads','select'),'browser read ledger has no DataAPI grant');reset role;select is((select count(*)from app.community_post_mentions where post_id=(select post from mention_fixture)),1::bigint,'post replay creates one exact recipient link');select*from finish();rollback;


